playInFullscreenWithAudio(video: HTMLVideoElement) {
  if (!this.isBrowser) return;
  if (document.fullscreenElement === video) return;

  video.requestFullscreen?.().then(() => {
    video.muted = false;
    video.volume = 1;

    video.play().catch(() => {});
  });

  const handleFullscreen = () => {
    if (!document.fullscreenElement) {
      // exited fullscreen → mute again
      video.muted = true;
      video.volume = 0;

      video.play().catch(() => {});

      document.removeEventListener(
        'fullscreenchange',
        handleFullscreen
      );
    }
  };

  document.addEventListener(
    'fullscreenchange',
    handleFullscreen
  );
}
